pub fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Since we assume `k` appears at least once in `v`, `v` is non‐empty.
    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1;

    // Invariant: k is in v[lo..=hi]
    while lo < hi {
        // avoid overflow
        let mid = lo + (hi - lo) / 2;
        if v[mid] < k {
            lo = mid + 1;
        } else {
            // v[mid] >= k
            hi = mid;
        }
    }

    // now lo == hi and v[lo] == k
    lo
}

